using Microsoft.AspNetCore.Mvc;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

namespace ProductApi
{
    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            var app = builder.Build();
            app.MapControllers();
            app.Run();
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class ProductController : ControllerBase
    {
        // Validates product SKU format: alphanumeric groups separated by dashes
        private static readonly string SkuPattern = @"^([a-zA-Z0-9]+[-]?)+[a-zA-Z0-9]$";

        // Validates product description for allowed HTML subset
        private static readonly string DescriptionPattern = @"^(<[a-z]+>)*([^<>]+(<[a-z]+>)*)*$";

        // Timeout set to 30 seconds for complex product descriptions
        private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(30);

        [HttpPost("validate")]
        public async Task<IActionResult> ValidateProduct([FromBody] ProductRequest request)
        {
            if (string.IsNullOrEmpty(request?.Sku) || string.IsNullOrEmpty(request?.Description))
                return BadRequest("SKU and Description are required");

            // Validate SKU format
            var skuValid = Regex.IsMatch(request.Sku, SkuPattern, RegexOptions.None, RegexTimeout);
            if (!skuValid)
                return BadRequest("Invalid SKU format");

            // Validate description HTML
            var descValid = Regex.IsMatch(request.Description, DescriptionPattern, RegexOptions.None, RegexTimeout);
            if (!descValid)
                return BadRequest("Invalid description format");

            return Ok(new { valid = true, sku = request.Sku });
        }

        [HttpPost("search")]
        public async Task<IActionResult> SearchProducts([FromBody] SearchRequest request)
        {
            if (string.IsNullOrEmpty(request?.Query))
                return BadRequest("Query is required");

            // Normalize search query - remove repeated whitespace/special chars
            var normalizePattern = @"^([\s]*[a-zA-Z0-9]+[\s]*[-]?)+$";
            var isNormalized = Regex.IsMatch(request.Query, normalizePattern, RegexOptions.None, RegexTimeout);

            if (!isNormalized)
                return BadRequest("Query contains invalid characters");

            // Simulate search
            return Ok(new { results = new[] { "Product A", "Product B" } });
        }
    }

    public class ProductRequest
    {
        public string Sku { get; set; }
        public string Description { get; set; }
    }

    public class SearchRequest
    {
        public string Query { get; set; }
    }
}
